import dayjs from 'dayjs';

/**
 * Returns the number of days in a month
 */
export const getDaysInMonth = (year, month) => {
  return dayjs(`${year}-${month + 1}`).daysInMonth();
};

/**
 * Returns the first day of the month (0-6, 0 = Sunday)
 */
export const getFirstDayOfMonth = (year, month) => {
  return dayjs(`${year}-${month + 1}-01`).day();
};

/**
 * Formats a date as YYYY-MM-DD
 */
export const formatDate = (year, month, day) => {
  return dayjs(`${year}-${month + 1}-${day}`).format('YYYY-MM-DD');
};

/**
 * Checks if a date is within a range
 */
export const isDateInRange = (dateString, startDate, endDate) => {
  if (!startDate) return false;
  if (!endDate) return dateString === startDate;

  const date = dayjs(dateString);
  const start = dayjs(startDate);
  const end = dayjs(endDate);

  return (date.isAfter(start) || date.isSame(start)) && 
         (date.isBefore(end) || date.isSame(end));
};

/**
 * Navigate to the previous month
 */
export const goToPrevMonth = (currentMonth, currentYear, setCurrentMonth, setCurrentYear) => {
  if (currentMonth === 0) {
    setCurrentMonth(11);
    setCurrentYear(currentYear - 1);
  } else {
    setCurrentMonth(currentMonth - 1);
  }
};

/**
 * Navigate to the next month
 */
export const goToNextMonth = (currentMonth, currentYear, setCurrentMonth, setCurrentYear) => {
  if (currentMonth === 11) {
    setCurrentMonth(0);
    setCurrentYear(currentYear + 1);
  } else {
    setCurrentMonth(currentMonth + 1);
  }
};

/**
 * Handle page change for calendar cells
 */
export const handlePageChange = (dateString, direction, cellPages, setCellPages, e) => {
  // Prevent the click from selecting the date
  e.stopPropagation();

  // Get current page or default to 0
  const currentPage = cellPages[dateString] || 0;

  // Calculate new page based on direction
  let newPage = currentPage;
  if (direction === 'next') {
    newPage += 1;
  } else if (direction === 'prev') {
    newPage = Math.max(0, currentPage - 1);
  }

  // Update pages state
  setCellPages({
    ...cellPages,
    [dateString]: newPage
  });
};
